const pj = fileURLToPath(new URL('../package.json', import.meta.url))
const pjDist = fileURLToPath(new URL('../../package.json', import.meta.url))
const { version } = JSON.parse(
  await readFile(pjDist, 'utf8').catch(() => readFile(pj, 'utf8')),
